-- 1117: Blog post — "WSQ Microsoft Azure Fundamentals (AZ-900) in Singapore: Exam Domains,
--       Funding and Free Practice Exams"
--
--       Lead-in post for the WSQ Microsoft Azure Fundamentals (AZ-900) course
--       (TGS-2023036449). Backdated to 2025-08-19 (published, status 1); no LinkedIn /
--       Facebook share is performed (linkedin_urn / facebook_post_id left NULL and the
--       post ships already-published, so publishDue never picks it up).
--
-- Every figure below was read off the LIVE course page on 2026-08-26, not invented:
--   * Fee card: full $800.00, GST $72.00 (9%), baseline nett $472.00 (SG/PR 21+, 50%),
--     MCES/SME nett $312.00 (SG 40+, 70%).
--   * Course information: 2 days / 16 hrs, Beginner, 2 hrs assessment.
--   * Funding validity 7 Aug 2023 - 6 Aug 2027; Absentee Payroll $4.50/hr capped $100,000.
--   * Badges present on the product: WSQ SFC PSEA UTAP SFEC Absentee Payroll MCES —
--     so each funding section in the copy corresponds to a badge the course actually has.
--   * Microsoft Learning Partner Org ID 5238476; Microsoft exams are delivered via
--     Pearson VUE. The copy does NOT claim we proctor the AZ-900 exam ourselves.
--   * "Free practice exams" is verified: the product page renders the "Bonus: Free
--     Practice Exams" card (cert-prep-tree gate) and
--     exams.tertiaryinfotech.com/practice-exams/microsoft/microsoft-az-900 returns 200.
--     Public-portal offer (10 free questions) vs participant benefit (unlimited) is
--     stated correctly — see memory feedback_free_practice_exams_claim_is_gated_by_cert_prep_tree.
--
-- Notes for future editors:
--  * apply.php splits statements on ";" at end-of-line — the content HTML below is ONE line.
--  * Idempotent: WHERE NOT EXISTS on url_key, INSERT IGNORE on tag links. Safe to re-run.
--  * SG-only guard via @mms_instance — the CTA course is SG WSQ, absent on MY/GH.
--  * hero_image_url is NOT set here (SQL cannot render one) — generate on prod post-deploy
--    via MMD_Blog_Model_Hero and bake the R2 URL in a follow-up migration (cf. 1109/1110).

SET @is_sg := IF(@mms_instance = 'SG', 1, 0);

INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `source_sku`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) SELECT 'WSQ Microsoft Azure Fundamentals (AZ-900) in Singapore: Exam Domains, Funding and Free Practice Exams', 'wsq-microsoft-azure-fundamentals-az-900-singapore-guide', 'Azure is the cloud most Singapore enterprises already run on, and AZ-900 is the credential that proves you understand it. This guide walks the four AZ-900 exam domains and their weightings, sets out exactly what you pay after WSQ funding - $472 nett, or $312 for Singapore Citizens aged 40 and above - and shows how to rehearse on our free AZ-900 practice exams before you book the real thing.', '<div class="mmd-summary"><div class="mmd-summary-label">Summary</div><p><strong>AZ-900: Microsoft Azure Fundamentals</strong> is the entry point to the Azure certification ladder and the fastest way to make cloud literacy visible on a CV. This guide covers why the credential is worth sitting, the four exam domains and their weightings, what the 2-day <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-azure-fundamentals-az-900.html">WSQ - Microsoft Azure Fundamentals (AZ-900)</a> course covers, and the funding that brings the $800 fee down to <strong>$472</strong> nett - or <strong>$312</strong> for Singapore Citizens aged 40 and above. Course participants also get free, unlimited AZ-900 practice exams on our Practice Exam Portal.</p></div> <h2>Why AZ-900 is worth sitting</h2> <p>Cloud fluency has quietly become a baseline expectation rather than a specialisation. Procurement officers evaluate SaaS contracts, finance teams sign off on consumption billing, and project managers scope migrations - none of them are engineers, and all of them are now expected to know what a region, a virtual network and a shared responsibility model actually are. AZ-900 is the certification built for exactly that gap.</p> <ul> <li><strong>No prerequisites, no engineering background required.</strong> AZ-900 is explicitly designed for candidates from non-technical as well as technical backgrounds. It is the one Azure exam you can sit without first proving anything else.</li> <li><strong>It is the gateway to the rest of the Azure ladder.</strong> Passing it gives you the vocabulary that AZ-104 (Administrator), AZ-204 (Developer) and AZ-305 (Solutions Architect) all assume you already have. Starting one rung higher is where most self-taught candidates come unstuck.</li> <li><strong>Azure is where the Singapore market is.</strong> Microsoft operates a Singapore Azure region, and the enterprises and government-linked organisations that standardised on Microsoft 365 tend to run their infrastructure on the same tenant. Skills in that stack transfer directly to the employers who are hiring.</li> <li><strong>The certification does not expire.</strong> Microsoft''s fundamentals-level certifications, AZ-900 included, have no renewal requirement - unlike role-based Azure certifications, which need annual renewal. You sit it once.</li> <li><strong>It de-risks the conversation about cost.</strong> A large share of cloud overspend traces back to people specifying resources they did not understand. The governance and cost-management portion of AZ-900 is disproportionately useful for anyone who signs off on a bill.</li> </ul> <h2>The AZ-900 exam at a glance</h2> <table><tbody> <tr><th>Certification</th><td>Microsoft Certified: Azure Fundamentals</td></tr> <tr><th>Exam code</th><td>AZ-900</td></tr> <tr><th>Level</th><td>Beginner / foundational</td></tr> <tr><th>Prerequisites</th><td>None</td></tr> <tr><th>Passing score</th><td>700 out of 1000 (scaled)</td></tr> <tr><th>Question types</th><td>Multiple choice, multiple response, drag-and-drop and case-based items</td></tr> <tr><th>Delivery</th><td>Pearson VUE - at a test centre or online proctored</td></tr> <tr><th>Renewal</th><td>Does not expire</td></tr> </tbody></table> <p>The scaled score matters more than it looks: 700/1000 is <em>not</em> 70% of the questions. Microsoft scales scores across item difficulty, so treat it as a threshold to clear comfortably rather than a percentage to calculate against.</p> <h2>AZ-900 exam domains and weightings</h2> <p>Microsoft publishes the weighting of each domain on the exam''s skills-measured page. Read them as a study budget - the heaviest domain deserves proportionally more of your revision time.</p> <table><thead><tr><th>Exam domain</th><th>Weighting</th><th>What it covers</th></tr></thead><tbody> <tr><td><strong>Describe cloud concepts</strong></td><td>25-30%</td><td>The shared responsibility model; public, private and hybrid cloud; consumption-based pricing and capital versus operating expenditure; and the benefits of cloud - high availability, scalability, elasticity, reliability, predictability, security, governance and manageability. Plus the service models: IaaS, PaaS and SaaS.</td></tr> <tr><td><strong>Describe Azure architecture and services</strong></td><td>35-40%</td><td>The largest domain. Core architectural components - regions, region pairs, availability zones, resource groups, subscriptions and management groups - then the compute services (virtual machines, containers, Azure Functions), networking (virtual networks, VPN Gateway, ExpressRoute, DNS) and storage services, plus Microsoft Entra ID and authentication.</td></tr> <tr><td><strong>Describe Azure management and governance</strong></td><td>30-35%</td><td>Cost management - the pricing and TCO calculators, budgets and tags; governance and compliance via Azure Policy, resource locks and the Service Trust Portal; the tools for deploying and managing resources (portal, Cloud Shell, CLI, PowerShell, Azure Arc, ARM templates); and monitoring with Azure Advisor, Service Health and Azure Monitor.</td></tr> </tbody></table> <p>Note how the exam is shaped: roughly two-thirds of it is services, management and governance rather than abstract cloud theory. Candidates who revise only the concepts chapter routinely underestimate this.</p> <h2>What the WSQ course covers</h2> <p>Our <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-azure-fundamentals-az-900.html">WSQ - Microsoft Azure Fundamentals (AZ-900)</a> runs over <strong>2 days (16 hours)</strong> at beginner level, with a 2-hour assessment. It is instructor-led and hands-on, delivered at our Woodlands Square training centre, with synchronous online delivery over Zoom and corporate in-house options available.</p> <ol> <li><strong>Get started on Azure cloud computing.</strong> Introduction to cloud computing, the benefits of cloud services, the types of cloud service, and the core architectural components of Azure.</li> <li><strong>Implementation of Azure compute and networking services.</strong> Azure Virtual Machines, containers and Functions; Azure virtual networking and storage services; and Azure identity, access and security.</li> <li><strong>Monitoring and managing Azure cloud solutions.</strong> Cost management in Azure; governance and compliance tooling; the tools for managing and deploying Azure resources; monitoring tools; and Azure Resource Manager.</li> </ol> <p>Because this is a WSQ-approved programme it is assessed against published learning outcomes - assess cloud solutions and specifications for Azure, develop an implementation plan, and develop review processes to resolve implementation issues. You leave with a Statement of Attainment as well as exam readiness.</p> <p><strong>Typical roles this supports:</strong> Cloud Support Associate, IT Administrator, Business Analyst, Project Manager, Sales and Pre-Sales Consultant, and anyone moving into an Azure-adjacent role.</p> <h2>Practise free before you book the exam</h2> <p>We are an <strong>Authorised Microsoft Learning Partner (Org ID: 5238476)</strong>. Microsoft certification exams are delivered through <strong>Pearson VUE</strong>, so you register your AZ-900 exam at a Pearson VUE test centre or take it online proctored.</p> <p><strong>Register for this course and you get free practice exams.</strong> Course participants get access to our <a href="https://exams.tertiaryinfotech.com/practice-exams/microsoft/microsoft-az-900" target="_blank" rel="noopener">AZ-900 practice exams</a>, where you can rehearse in realistic <strong>Practice Mode</strong> and under timed <strong>Exam Mode</strong> conditions, then <strong>retake them as many times as you like</strong> before the real thing.</p> <p>This matters more than it sounds. The best predictor of passing a certification exam first time is how many realistic practice questions you sat beforehand - not how many hours of content you watched. Practising under timed conditions is also what stops the clock being the thing that beats you on exam day.</p> <p><a href="https://exams.tertiaryinfotech.com/practice-exams/microsoft/microsoft-az-900" target="_blank" rel="noopener"><strong>Start practising AZ-900 at exams.tertiaryinfotech.com &rarr;</strong></a></p> <h2>What you actually pay: funding for AZ-900 training</h2> <p>This is a <strong>WSQ-approved course (course reference <code>TGS-2023036449</code>)</strong>, so the published fee is not what most learners pay. The schemes stack in a specific order: the baseline subsidy comes off first, then credits and claims are applied to what remains.</p> <table><thead><tr><th>Your profile</th><th>What you pay (nett)</th></tr></thead><tbody> <tr><td>Full fee (before funding)</td><td>$800.00 + $72.00 GST</td></tr> <tr><td>Singapore Citizen / PR aged 21+ &mdash; 50% funded</td><td><strong>$472.00</strong></td></tr> <tr><td>Singapore Citizen aged 40+ (MCES), or SME-sponsored &mdash; 70% funded</td><td><strong>$312.00</strong></td></tr> </tbody></table> <p>On top of the baseline subsidy, several schemes can reduce the out-of-pocket amount further.</p> <h3>1. SkillsFuture Credit (SFC)</h3> <p>Singapore Citizens aged 25 and above can offset the <em>remaining</em> fee payable after funding with their SkillsFuture Credit. One restriction applies: the $4,000 Additional SkillsFuture Credit (Mid-Career Support) cannot be used on this course. You can <a href="https://courses.myskillsfuture.gov.sg/courses/TGS-2023036449" target="_blank" rel="noopener">apply directly on the MySkillsFuture portal</a> using course code TGS-2023036449.</p> <h3>2. SkillsFuture Enterprise Credit (SFEC)</h3> <p>Sponsoring employees? Eligible Singapore-registered companies can draw on <strong>up to $10,000 of SFEC</strong> to cover out-of-pocket expenses. Look the course up on <a href="https://skillsfuture.gobusiness.gov.sg/course-directory/courses/TGS-2023036449" target="_blank" rel="noopener">SkillsFuture for Business</a>.</p> <h3>3. PSEA</h3> <p>Eligible Singapore Citizens can pay the remaining fee from their <strong>Post-Secondary Education Account</strong>. Check the course listing on MySkillsFuture, look under &ldquo;Keyword Tags&rdquo; for a PSEA tag to confirm eligibility, then submit a PSEA withdrawal form to us.</p> <h3>4. UTAP</h3> <p>NTUC members can claim <strong>50% of the unfunded course fee</strong> through the Union Training Assistance Programme, capped at $250 per year, or <strong>$500 per year for members aged 40 and above</strong>. Claims are submitted after course completion via the <a href="https://utap.ntuc.org.sg/onlineClaim" target="_blank" rel="noopener">NTUC UTAP portal</a>. UTAP support is course-specific and subject to NTUC approval at the time of your claim.</p> <h3>5. Absentee Payroll</h3> <p>Employers sponsoring staff may claim <strong>Absentee Payroll</strong> at $4.50 per hour, capped at $100,000 per enterprise per calendar year, computed on the actual training hours attended.</p> <p><strong>Funding validity:</strong> funding for this course is valid from <strong>7 Aug 2023 to 6 Aug 2027</strong>. Register and complete the course within this window to qualify for support.</p> <p><em>All funding is subject to eligibility and to the prevailing SSG policies at the time of course commencement. Talk to us before you enrol and we will work out your exact nett fee.</em></p> <h2>Your route to certification</h2> <ol> <li><strong>Check your funding eligibility.</strong> Your citizenship, age band and whether an employer is sponsoring you determine whether you pay $472, $312 or less.</li> <li><strong>Register for the course.</strong> Pick a class date on the <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-azure-fundamentals-az-900.html">course page</a> and reserve your seat.</li> <li><strong>Attend the 2-day instructor-led training.</strong> Complete the hands-on work and the WSQ assessment to earn your Statement of Attainment.</li> <li><strong>Rehearse on the practice exams.</strong> Work through Practice Mode, then sit timed Exam Mode runs until you are clearing the threshold consistently.</li> <li><strong>Book and sit AZ-900 with Pearson VUE.</strong> At a test centre or online proctored - while the material is still fresh.</li> <li><strong>Submit your claims.</strong> Offset with SkillsFuture Credit or PSEA, and submit your UTAP claim after completion.</li> </ol> <h2>Where to go after AZ-900</h2> <p>AZ-900 is deliberately a starting point. The usual next rung for anyone heading into infrastructure work is <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-certified-azure-administrator-associate-az-104.html">WSQ - Microsoft Certified Azure Administrator Associate (AZ-104)</a>, which takes the concepts you have just learned and turns them into the day-to-day administration of identities, storage, networking and compute. The rest of the <a href="https://www.tertiarycourses.com.sg/azure-cloud-computing-courses.html">Azure cloud computing courses</a> and the wider <a href="https://www.tertiarycourses.com.sg/microsoft-certifications-exams.html">Microsoft certification exam prep</a> range map out the ladder from there.</p> <p>If you would rather build vendor-neutral breadth first, our <a href="https://www.tertiarycourses.com.sg/wsq-comptia-certified-cloud-training.html">WSQ CompTIA Cloud+ training</a> covers cloud operations across providers, and the <a href="https://www.tertiarycourses.com.sg/wsq-aws-certified-cloud-practitioner-training.html">WSQ AWS Certified Cloud Practitioner course</a> is the equivalent entry point in the AWS ecosystem.</p> <h2>Frequently asked questions</h2> <div class="mmd-faq"> <details class="mmd-faq-item"><summary class="mmd-faq-q">Do I need an IT background to take AZ-900?</summary><div class="mmd-faq-a"><p>No. AZ-900 has no prerequisites and is designed for both technical and non-technical candidates. It is routinely taken by project managers, sales and pre-sales staff, procurement and finance colleagues who need to be conversant in cloud without being engineers.</p></div></details> <details class="mmd-faq-item"><summary class="mmd-faq-q">Is the exam included in the course fee?</summary><div class="mmd-faq-a"><p>No. The course fee covers the instructor-led training, courseware and the WSQ assessment. The AZ-900 exam is registered and paid for separately with Pearson VUE, either at a test centre or online proctored.</p></div></details> <details class="mmd-faq-item"><summary class="mmd-faq-q">Do I need to pass AZ-900 to keep the funding?</summary><div class="mmd-faq-a"><p>No. Course fee funding is tied to attending the course and being assessed competent in the <em>WSQ assessment</em>, not to the Microsoft exam. Meeting the minimum attendance requirement and passing the assessment secures the subsidy and your Statement of Attainment.</p></div></details> <details class="mmd-faq-item"><summary class="mmd-faq-q">What will I actually pay?</summary><div class="mmd-faq-a"><p>The full fee is $800 before GST. Eligible Singapore Citizens and PRs aged 21 and above pay <strong>$472 nett</strong> at 50% funding; Singapore Citizens aged 40 and above (MCES) and SME-sponsored employees pay <strong>$312 nett</strong> at 70% funding. SkillsFuture Credit, PSEA and UTAP can be applied to what remains.</p></div></details> <details class="mmd-faq-item"><summary class="mmd-faq-q">How long is the certification valid?</summary><div class="mmd-faq-a"><p>Microsoft Certified: Azure Fundamentals does not expire. Unlike the role-based Azure certifications, fundamentals-level credentials carry no annual renewal requirement.</p></div></details> <details class="mmd-faq-item"><summary class="mmd-faq-q">Are the practice exams really free and unlimited?</summary><div class="mmd-faq-a"><p>For course participants, yes - you get access to the AZ-900 practice exams on our Practice Exam Portal in both Practice Mode and timed Exam Mode, and you can retake them as many times as you like. The portal''s public offer to non-participants is limited to 10 free questions per exam.</p></div></details> </div> <h2>Register for AZ-900 training</h2> <p>Seats are limited and classes fill ahead of each intake. View the upcoming dates and reserve your place on the <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-azure-fundamentals-az-900.html"><strong>WSQ - Microsoft Azure Fundamentals (AZ-900)</strong></a> course page, or call us on +65 6100 0613 if you would like your funding worked out first.</p>', 'Tertiary Infotech Academy', 1, '2025-08-19', 'TGS-2023036449', 'TGS-2023036449', 'WSQ Microsoft Azure Fundamentals AZ-900 Singapore: Exam Domains and Funding', 'Train for Microsoft Azure Fundamentals (AZ-900) in Singapore. 2-day WSQ course from $312 nett after funding, full AZ-900 exam domain breakdown, and free unlimited AZ-900 practice exams for participants.', 'az-900 course singapore, microsoft azure fundamentals certification, az-900 exam prep, wsq azure course, azure training singapore, skillsfuture azure certification, az-900 practice exam, microsoft certified azure fundamentals', '2025-08-19 09:00:00', '2025-08-19 09:00:00' FROM DUAL WHERE @is_sg > 0 AND NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'wsq-microsoft-azure-fundamentals-az-900-singapore-guide');

-- Tags (core Magento tag vocabulary; status 1 = approved)
INSERT INTO `tag` (`name`, `status`) SELECT 'Microsoft', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `tag` WHERE `name` = 'Microsoft');
INSERT INTO `tag` (`name`, `status`) SELECT 'Azure', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `tag` WHERE `name` = 'Azure');
INSERT INTO `tag` (`name`, `status`) SELECT 'AZ-900', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `tag` WHERE `name` = 'AZ-900');
INSERT INTO `tag` (`name`, `status`) SELECT 'Cloud Computing', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `tag` WHERE `name` = 'Cloud Computing');
INSERT INTO `tag` (`name`, `status`) SELECT 'WSQ', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `tag` WHERE `name` = 'WSQ');

SET @post_id := (SELECT `post_id` FROM `mmd_blog_post` WHERE `url_key` = 'wsq-microsoft-azure-fundamentals-az-900-singapore-guide');

INSERT IGNORE INTO `mmd_blog_post_tag` (`post_id`, `tag_id`) SELECT @post_id, `tag_id` FROM `tag` WHERE @post_id IS NOT NULL AND `name` IN ('Microsoft', 'Azure', 'AZ-900', 'Cloud Computing', 'WSQ');

